## 2. probléma: Safari keret megjelenik a bejelentkezés alatt

**A nyilvánvaló megoldás** lett volna natív `ASWebAuthenticationSession` vagy `SFSafariViewController` — ez csak Swift/SwiftUI-ban elérhető, tehát PWA-ban nem opció.

**A második legjobb megközelítés: Universal Login iframe + Auth0 silent-first + saját átmeneti overlay.**

A lényeg: ahelyett, hogy a böngésző teljesen átnavigál az Auth0 oldalra (ahol megjelenik a Safari cím- és eszközsáv), a bejelentkezési folyamatot egy **saját full-screen overlay-ben** indítod, és a redirect visszatérése után **észrevétlenül befejezed** a háttérben — a felhasználó soha nem látja a böngésző natív keretét.

### A teljes `_doLogin` + kapcsolódó kód cseréje:

```javascript
// ─── Saját login overlay iframe megközelítés ───────────────────────────────
// Létrehozunk egy full-screen natívnak látszó overlay-t, majd azon belül
// kezelünk mindent — Safari soha nem mutatja a saját chrome-ját.

function _buildLoginFrame(url) {
  // Ha már van, töröljük
  const old = document.getElementById('_auth_frame_wrap');
  if (old) old.remove();

  const wrap = document.createElement('div');
  wrap.id = '_auth_frame_wrap';
  wrap.style.cssText = [
    'position:fixed', 'inset:0', 'z-index:999999',
    'background:var(--bg,#000)',
    'display:flex', 'flex-direction:column',
    'opacity:0', 'transition:opacity .22s cubic-bezier(.2,1,.3,1)',
    // Safe area
    'padding-top:env(safe-area-inset-top,0px)',
    'padding-bottom:env(safe-area-inset-bottom,0px)',
  ].join(';');

  // Fejléc — úgy néz ki mint egy natív modal header
  const hdr = document.createElement('div');
  hdr.style.cssText = [
    'display:flex', 'align-items:center', 'justify-content:space-between',
    'padding:12px 16px', 'flex-shrink:0',
    'border-bottom:.5px solid rgba(255,255,255,.08)',
  ].join(';');

  const title = document.createElement('span');
  title.textContent = 'Bejelentkezés';
  title.style.cssText = 'font-size:15px;font-weight:600;color:var(--fg,#f5f5f7);flex:1;text-align:center;';

  const closeBtn = document.createElement('button');
  closeBtn.textContent = 'Mégse';
  closeBtn.style.cssText = [
    'background:none', 'border:none', 'color:var(--blue-l,#147CE5)',
    'font-size:15px', 'cursor:pointer', 'padding:4px 0',
    'font-family:inherit', 'flex-shrink:0',
  ].join(';');
  closeBtn.addEventListener('click', () => _closeLoginFrame());

  // Spacer a szimmetriához
  const spacer = document.createElement('span');
  spacer.style.cssText = 'width:52px;flex-shrink:0;';

  hdr.appendChild(spacer);
  hdr.appendChild(title);
  hdr.appendChild(closeBtn);

  // Az iframe maga
  const frame = document.createElement('iframe');
  frame.id = '_auth_iframe';
  frame.src = url;
  frame.style.cssText = [
    'flex:1', 'border:none', 'width:100%',
    'background:transparent',
  ].join(';');
  // Sandboxing: engedélyezzük a form submit-ot, JS-t, same-origin-t, popups-t
  frame.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-popups allow-top-navigation-by-user-activation');
  frame.setAttribute('allow', 'identity-credentials-get');

  wrap.appendChild(hdr);
  wrap.appendChild(frame);
  document.body.appendChild(wrap);

  // Fade-in animáció
  requestAnimationFrame(() => {
    requestAnimationFrame(() => { wrap.style.opacity = '1'; });
  });

  return wrap;
}

function _closeLoginFrame() {
  const wrap = document.getElementById('_auth_frame_wrap');
  if (!wrap) return;
  wrap.style.opacity = '0';
  wrap.style.transition = 'opacity .18s cubic-bezier(.4,0,1,1)';
  setTimeout(() => wrap.remove(), 200);
}

// Az URL-callback figyelő: ha az iframe az origin-ünkre navigál vissza
// (Auth0 redirect_uri), elkapjuk és a főablakban dolgozzuk fel
function _watchFrameRedirect(frame) {
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      reject(new Error('Login timeout'));
    }, 300000); // 5 perc

    const check = () => {
      try {
        const loc = frame.contentWindow?.location?.href || '';
        if (loc && loc.startsWith(window.location.origin) && loc.includes('code=')) {
          clearTimeout(timeout);
          clearInterval(interval);
          resolve(loc);
        }
      } catch (_) {
        // Cross-origin: még az Auth0 oldalon vagyunk, normális
      }
    };
    const interval = setInterval(check, 300);
    frame.addEventListener('load', check);
  });
}

async function _doLogin() {
  if (!_auth0Client) return;
  const params = { authorizationParams: { connection: 'apple' } };

  // PWA módban: popup még mindig a legjobb (valóban natív, nincs Safari chrome)
  if (_isPWA()) {
    try {
      await _auth0Client.loginWithPopup(params);
      await _handleSuccessfulLogin();
      return;
    } catch (e) {
      console.warn('PWA popup failed, falling back to frame method', e);
      // Esés: iframe módra váltunk
    }
  }

  // ── Iframe-alapú megközelítés (nem PWA, vagy popup fallback) ──────────────
  // 1. Létrehozzuk az Auth0 authorization URL-t manuálisan
  try {
    // Auth0 SPA SDK-val lekérjük az auth URL-t anélkül, hogy navigálnánk
    const authUrl = await _buildAuthUrl(params);
    if (!authUrl) throw new Error('No auth URL');

    const wrap = _buildLoginFrame(authUrl);
    const frame = document.getElementById('_auth_iframe');

    // 2. Várjuk, hogy az iframe visszanavigáljon az originünkre
    let callbackUrl;
    try {
      callbackUrl = await _watchFrameRedirect(frame);
    } catch (e) {
      _closeLoginFrame();
      return;
    }

    // 3. Feldolgozzuk a callback-et a háttérben, az iframe URL-jét
    //    szimulálva a főablakban — de CSAK átmenetileg, láthatatlanul
    _closeLoginFrame();

    // Az Auth0 SDK handleRedirectCallback-je az aktuális URL alapján dolgozik.
    // Átmenetileg beállítjuk a history-t, meghívjuk, majd visszaállítjuk.
    const originalUrl = window.location.href;
    window.history.replaceState({}, '', callbackUrl);
    try {
      await _auth0Client.handleRedirectCallback();
    } catch (cbErr) {
      console.error('handleRedirectCallback error', cbErr);
      window.history.replaceState({}, '', originalUrl);
      _showAuthError('Bejelentkezési hiba: ' + (cbErr?.message || cbErr));
      return;
    }
    window.history.replaceState({}, '', originalUrl);

    await _handleSuccessfulLogin();

  } catch (err) {
    console.error('Frame login error, falling back to redirect', err);
    // Végső fallback: sima redirect — de ezt kerüljük
    _auth0Client.loginWithRedirect(params);
  }
}

// Auth URL manuális felépítése az Auth0 SDK internal API-n keresztül
async function _buildAuthUrl(params) {
  try {
    // Az Auth0 SPA SDK 2.x-ben van checkSession/buildAuthorizeUrl
    if (typeof _auth0Client.buildAuthorizeUrl === 'function') {
      return await _auth0Client.buildAuthorizeUrl(params);
    }
    // Alternatíva: a getTokenSilently-t error-ra futtatjuk, az URL-t a
    // redirect_uri-ból rekonstruáljuk — ez az oka, hogy a cfg-ből dolgozunk
    const cfg = _auth0Client.options || {};
    const base = ``;
    const p = new URLSearchParams({
      response_type: 'code',
      client_id: cfg.clientId,
      redirect_uri: window.location.origin,
      scope: 'openid profile email offline_access',
      state: Math.random().toString(36).slice(2),
      nonce: Math.random().toString(36).slice(2),
      connection: 'apple',
      ...((params.authorizationParams) || {}),
    });
    return `${base}?${p}`;
  } catch (e) {
    console.warn('buildAuthUrl failed', e);
    return null;
  }
}

async function _handleSuccessfulLogin() {
  const authed = await _auth0Client.isAuthenticated();
  if (!authed) return;
  try {
    _accessToken = await _auth0Client.getTokenSilently();
  } catch (_) {
    _accessToken = null;
  }
  // UI csere: login overlay eltüntetése, app megjelenítése
  const loginOverlay = document.getElementById('login-overlay');
  const appEl = document.getElementById('app');
  // Sima, animált átmenet — natívnak hat
  loginOverlay.style.transition = 'opacity .28s cubic-bezier(.4,0,1,1)';
  loginOverlay.style.opacity = '0';
  setTimeout(() => {
    loginOverlay.style.display = 'none';
    loginOverlay.style.opacity = '';
    loginOverlay.style.transition = '';
    appEl.style.display = '';
  }, 280);
  try {
    const u = await _auth0Client.getUser();
    if (u) {
      const displayName = u.name || u.email || '';
      const nameEl = document.getElementById('sb-user-name');
      const avatarEl = document.getElementById('sb-user-avatar');
      const infoEl = document.getElementById('sb-user-info');
      if (nameEl) nameEl.textContent = displayName;
      if (avatarEl) avatarEl.textContent = (displayName[0] || '?').toUpperCase();
      if (infoEl) infoEl.style.display = '';
    }
  } catch (_) {}
}
```

***

## Összefoglalás — mi miért működik

| Probléma | Javítás módja | Miért jobb |
|---|---|---|
| **App alja lebeg** | `max(var(--sab), env(...))` + `translateZ(0)` + `visualViewport.offsetTop` kompenzáció | A CSS `env()` közvetlenül a böngészőtől jön, nem JS-től; az `offsetTop` a keyboard-toló effektust is kezeli |
| **Safari keret** | Full-screen custom iframe overlay, `_watchFrameRedirect`, háttérbeli `handleRedirectCallback` | A felhasználó soha nem látja a Safari address/tab bart — minden az app saját overlay-én belül történik |

A megoldás szándékosan kerüli az `ASWebAuthenticationSession`-t (csak natív app) és az `SFSafariViewController`-t (szintén csak natív) — ez a legjobb elérhető webes megközelítés .
